  if (!isAdmin || !session) {
    forbidden()
  }

  return (
    <main
      style={{
        maxWidth: '42rem',
        margin: '0 auto',
        padding: '3rem 1.5rem',
        fontFamily: 'system-ui, sans-serif',
      }}
    >
// ... rest of admin dashboard UI
```

```1:9:/vercel/sandbox/next.config.ts
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  experimental: {
    authInterrupts: true,
  },
}

export default nextConfig
```

